import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadVellodeData(){const e=readFileSync(resolve(__dirname,"../../frontend/vellode-wetland-explorer/vellode-data.js"),"utf-8");return new Function(e+"\nreturn { VELLODE_INFO, ECOLOGY_HYDROLOGY, INTERESTING_FACTS, BIRD_SPECIES, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadWetlandsLandingData(){let e=readFileSync(resolve(__dirname,"../../frontend/wetlands/wetlands-data.js"),"utf-8");e=e.replace(/export\s+const\s+/g,"const ");return new Function(e+"\nreturn WETLANDS_DATA;")()}describe("Vellode Wetland Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadVellodeData()}),describe("VELLODE_INFO metadata",()=>{it("contains correct wetland metadata and status",()=>{expect(e.VELLODE_INFO.id).toBe("vellode-wetland"),expect(e.VELLODE_INFO.name).toContain("Vellode"),expect(e.VELLODE_INFO.ramsarYear).toBe(2022),expect(e.VELLODE_INFO.ramsarSiteNo).toBe(2482),expect(e.VELLODE_INFO.state).toBe("Tamil Nadu")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.VELLODE_INFO.quickStats)).toBe(!0),expect(e.VELLODE_INFO.quickStats.length).toBe(6)})}),describe("ECOLOGY_HYDROLOGY & INTERESTING_FACTS",()=>{it("contains overview, hydrology, history, and status",()=>{expect(e.ECOLOGY_HYDROLOGY.overview).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.hydrology).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.history).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.conservationStatus).toBeDefined()}),it("contains interesting facts array",()=>{expect(Array.isArray(e.INTERESTING_FACTS)).toBe(!0),expect(e.INTERESTING_FACTS.length).toBeGreaterThanOrEqual(3)})}),describe("BIRD_SPECIES catalog",()=>{it("is a non-empty array of species",()=>{expect(Array.isArray(e.BIRD_SPECIES)).toBe(!0),expect(e.BIRD_SPECIES.length).toBeGreaterThanOrEqual(4)}),it("includes Spot-billed Pelican and Oriental Darter",()=>{const t=e.BIRD_SPECIES.find(e=>"spot-billed-pelican"===e.id),a=e.BIRD_SPECIES.find(e=>"oriental-darter"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined()})}),describe("Landing Page Integration",()=>{it("is integrated in WETLANDS_DATA landing page dataset",()=>{const e=loadWetlandsLandingData().wetlands.find(e=>"vellode-wetland"===e.id);expect(e).toBeDefined(),expect(e.exploreUrl).toBe("../vellode-wetland-explorer/index.html")})})});